// Generates the compiled prompt bundle used by the main process.
// Source defaults to the desktop master suites; the generated file is the runtime source of truth.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { gzipSync } from 'node:zlib'

const root = process.env.MORROW_CREATIVE_SOURCE?.trim() || join(homedir(), 'Desktop', '写作+编剧+导演')

const masters = {
  writing: { folders: ['写作', 'writing'], methodology: ['方法论', 'methodology'] },
  screenwriting: { folders: ['编剧', 'screenwriting'], methodology: [] },
  directing: { folders: ['导演', 'directing'], methodology: ['方法论', 'methodology'] }
}

function findDir(base, names) {
  for (const name of names) {
    const dir = join(base, name)
    if (existsSync(join(dir, 'SKILL.md'))) return dir
  }
  return null
}

function findSubdir(base, names) {
  for (const name of names) {
    const dir = join(base, name)
    if (existsSync(dir)) return dir
  }
  return null
}

function readMaster(name, spec) {
  const dir = findDir(root, spec.folders)
  if (!dir) throw new Error(`找不到 ${name} 套组：${root}`)
  const skill = readFileSync(join(dir, 'SKILL.md'), 'utf8')
  const methodology = {}
  if (spec.methodology.length) {
    const methodDir = findSubdir(dir, spec.methodology)
    if (methodDir) {
      for (const file of readdirSync(methodDir).filter((item) => item.endsWith('.md')).sort()) {
        methodology[file] = readFileSync(join(methodDir, file), 'utf8')
      }
    }
  }
  return { skill, methodology }
}

const payload = { version: 1, masters: {} }
for (const [name, spec] of Object.entries(masters)) payload.masters[name] = readMaster(name, spec)

const json = JSON.stringify(payload)
const compressed = gzipSync(Buffer.from(json, 'utf8'), { level: 9 })
const base64 = compressed.toString('base64')
const counts = Object.fromEntries(Object.entries(payload.masters).map(([name, value]) => [name, {
  skill: Buffer.byteLength(value.skill),
  methodology: Object.keys(value.methodology).length,
  methodologyBytes: Object.values(value.methodology).reduce((sum, text) => sum + Buffer.byteLength(text), 0)
}]))
const header = [
  '// AUTO-GENERATED by scripts/embed-creative-prompts.mjs. Do not edit by hand.',
  '// The three master suites are embedded as a gzip+base64 bundle; no loose prompt files ship with the app.',
  `// ${JSON.stringify(counts)}`,
  ''
].join('\n')
writeFileSync(join(process.cwd(), 'src', 'main', 'creative-prompts.generated.ts'), `${header}export const CREATIVE_PROMPTS_GZIP_BASE64 = '${base64}'\n`)
console.log('embedded creative prompts', counts, 'json bytes', Buffer.byteLength(json), 'bundle bytes', Buffer.byteLength(base64))
